package channel

/**
 * 支付宝对接用的 RSA 密钥对（**已废弃的测试密钥，不对应任何真实商户**）。
 *
 * 抽成共用 fixture 而不是各测试类各存一份：下单签名与回调验签必须用同一对密钥，
 * 两份副本一旦漂移，表现是一边过、另一边一直「验签失败」—— 而支付宝不会告诉你差在哪。
 * 共用一份就把这种漂移变成不可能。
 */
object AlipayTestKeys {
    /** 我方私钥（PKCS#8 base64），用于给请求签名。 */
    const val PRIVATE_KEY = ""

    /** 与之配对的公钥，测试里充当「支付宝公钥」用于验回调签名。 */
    const val PUBLIC_KEY = ""
}
